        }
        const bool isServer = (rankId_ < remoteRank);
        for (uint32_t qpIdx = 0; qpIdx < qpNum_; ++qpIdx) {
            auto& desc = channelDescs[chIdx];
            desc.remoteEndpoint.protocol = COMM_PROTOCOL_ROCE;
